patternver="0100.0009"
-- 定义漏洞匹配找到的信息类型
BaseType = {
    kb = 1,
    dll = 2,
    exe = 3,
    sys = 4,
    Windows_version = 5,
    Windows_build = 6,
    Windows_revison_number = 7,
    app = 8
}

VulType = {
    OS = 1,
    App = 2,
    Web = 3,
    db = 4
}

-- 定义漏洞匹配查找的匹配动作
BaseOper = {
    lessthan = 1,
    equalto = 2,
    greaterthan = 3,
    notinstalled = 4
}

BaseOS = {
    Windows_xp = 1000,
    Windows_7 = 1001,
    Windows_Server_2003 = 1002,
    Windows_Vista = 1003,
    Windows_Server_2008_R2 = 1004,
    Windows_Server_2008 = 1005,
    Windows_Server_2012_R2 = 1006,
    Windows_Server_2012 = 1007,
    Windows_8_1 = 1008,
    Windows_10 = 1009,
    Windows_Server_2016 = 1010,
    Windows_Server_2019 = 1011,
    Windows_Server_2022 = 1012,
    Windows_11 = 1013,
    All = 1099
}

local gc_count = 500
local ruleList = {}
local Windows_version = nil
local Windows_build = nil
local Windows_revison_number = nil
local Windows_InstallKB = nil
local File_Version = {}
local OS_Type = nil

-- 所有的模块都通过这个函数来实现添加
function AddModule(module_id)
    collectgarbage("stop")
    ruleList[#ruleList + 1] = module_id
    if math.mod(#ruleList,gc_count) == 0 then
        collectgarbage("collect")
    end
end

function GetModule() 
    return ruleList 
end

function GetWindowsVersion() 
    return Windows_version 
end

function GetOsType() 
    return OS_Type 
end

function GetWindowsBuild() 
    return Windows_build 
end

function GetWindowsRevisonNumber() 
    return Windows_revison_number 
end

function GetInstallKB() 
    return Windows_InstallKB 
end

-- function GetAppVersion(filename)
--     ---print(filename)
--     if File_Version[filename] == nil then
--         File_Version[filename] = extendFunc.GetAppVersion(filename)
--         --File_Version[filename] = "0"
--     end
--     --print(File_Version[filename])
--     return File_Version[filename]
-- end

function GetFileVersion(filename)
    ---print(filename)
    if File_Version[filename] == nil then
        File_Version[filename] = extendFunc.GetFileVersion(filename)
        --File_Version[filename] = "0"
    end
    --print(File_Version[filename])
    return File_Version[filename]
end

function FileVersionCompare(Version1, Version2)
    if Version1==nil or Version2==nil then
        return BaseOper.lessthan
    end
    local V1 = {}
    local V2 = {}
    local len

    for w in string.gmatch(Version1, '[%w]+') do
        V1[#V1+1] = w
    end

    for w in string.gmatch(Version2, '[%w]+') do
        V2[#V2+1] = w
    end
    len = #V1
    if len>#V2 then
        len = #V2
    end

    for i=1,len do
        if #V1[i]>#V2[i] then
            return BaseOper.greaterthan
        elseif #V1[i]<#V2[i] then
            return BaseOper.lessthan
        end
        if V1[i]>V2[i] then
            return BaseOper.greaterthan
        elseif V1[i]<V2[i] then
            return BaseOper.lessthan
        end
    end
    return BaseOper.equalto
end




function InitGetInfo()
    -- 初始化一次
    --Windows_version = "21H1" -- extendFunc.GetWindowsVersion()
    --Windows_build = "19043" -- extendFunc.GetWindowsBuild()
    --Windows_revison_number = "1165" -- extendFunc.GetWindowsRevisonNumber()
    --Windows_InstallKB = "KB4422" -- extendFunc.GetInstallKB()
    --OS_Type = "Microsoft Windows 10" -- extendFunc.Os_Type()
    Windows_version = extendFunc.GetWindowsVersion()
    Windows_build = extendFunc.GetWindowsBuild()
    Windows_revison_number = extendFunc.GetWindowsRevisonNumber()

    local f = io.popen('systeminfo | find "KB"', 'r')
    Windows_InstallKB = f:read('*all')
    f:close()
    --Windows_InstallKB = extendFunc.GetInstallKB()
    OS_Type = extendFunc.GetWindowsOs()
    -- local filename = "KB4556853";
    -- if string.find(Windows_InstallKB, filename) ~= nil then
    --     print("find KB--------------");
    -- end

    -- print(Windows_version);
    -- print(Windows_build);
    -- print(Windows_revison_number);
    -- print(Windows_InstallKB);
    -- print(OS_Type);

    ---获取Windows系统类型
    local type = ""
    for w in string.gmatch(string.lower(OS_Type), '[%w]+') do
        type = type .. w
    end

    local oslist = {
        "microsoftwindowsxp", "microsoftwindows7", "microsoftwindowsserver2003",
        "microsoftwindowsvista", "microsoftwindowsserver2008r2",
        "microsoftwindowsserver2008", "microsoftwindowsserver2012r2",
        "microsoftwindowsserver2012", "microsoftwindows81",
        "microsoftwindows10", "microsoftwindowsserver2016",
        "microsoftwindowsserver2019","microsoftwindowsserver2022","microsoftwindows11"
    }
    for key0, value0 in pairs(oslist) do
        if string.find(type, value0) ~= nil then
            OS_Type = key0 + 999
            break
        end
    end

	--print(OS_Type)
    return
end

InitGetInfo()

