----------------------------------------------------------------------------------------
--              所有的pattern 都必须继承自该类。并实现其中的Scan                 --
----------------------------------------------------------------------------------------
--- the base class of VulRule

VulRule = {
    PatchId = "",
    CVEId = "",
    description = "",
    CVEType = VulType.OS,

    criteria = {
        OS = nil,
        logic = {Type = nil, filename = nil, Version = nil, Oper = nil}
    }

}

function VulRule:new(r)
    r = r or {}
    self.__index = self
    setmetatable(r, self)
    return r
end

function VulRule:Scan()
    local Bfind = false
    ---print(self.CVEId)
    for _, tab in ipairs(self.criteria) do
        ---print(tab.OS)
        if tab.OS == GetOsType() or tab.OS == BaseOS.All then
            Bfind = true
            Binstall = false
            for _, value in pairs(tab.logic) do
                local Oper = value["Oper"]
                local Type = value["Type"]
                local filename = value["filename"]
                local Version = value["Version"]
                ---已经安装更新
                if Type == BaseType.kb then
                    Binstall = true
                    if string.find(GetInstallKB(), filename) ~= nil then
                        Bfind = false
                        break
                    end
                    ---文件版本号比较
                elseif Type == BaseType.dll or Type == BaseType.exe or Type == BaseType.sys then
                    local filever = GetFileVersion(filename)
                    if not Binstall and FileVersionCompare(filever, "0") == BaseOper.greaterthan then
                        Binstall = true
                    end
                    if FileVersionCompare(filever, Version) ~= Oper then
                        Bfind = false
                        break
                    end
                    ---应用版本号比较

                elseif Type == BaseType.Windows_version then
                    Binstall = true
                    if FileVersionCompare(GetWindowsVersion(), Version) ~= Oper then
                        Bfind = false
                        break
                    end
                elseif Type == BaseType.Windows_build then
                    Binstall = true
                    if FileVersionCompare(GetWindowsBuild(), Version) ~= Oper then
                        Bfind = false
                        break
                    end
                elseif Type == BaseType.Windows_revison_number then
                    Binstall = true
                    if FileVersionCompare(GetWindowsRevisonNumber(), Version) ~= Oper then
                        Bfind = false
                        break
                    end
                end

                ---for key0, value0 in pairs(value) do
                ---	print("\t", key0, "===>", value0)
                ---end
            end

            if Bfind and Binstall then
                ---print(self.CVEId)
                ---print(tab.OS)
                return true
            end
        end
    end
    return false
end

function VulRule:createScanResult() return self.PatchId,self.CVEId,self.description,self.CVEType end

