--collectgarbage("restart")
local allrule = GetModule()

local for_count = 1
local result = {}
function ScanFun()
    local result = "{\"result\":["
	local bfind = false
---扫描所有规则
    for _, v in pairs(allrule) do 
        collectgarbage("stop")
		if v:Scan() then
			local PatchId,CVEId,description,CVEType = v:createScanResult()
			if bfind then
				result = table.concat{result, ",{\"Patchid\":\"", PatchId, "\",\"CveId\":\"",CVEId,"\",\"Type\":\"",CVEType,"\",\"desc\":\"", description, "\"}"}
			else
				result = table.concat{result, "{\"Patchid\":\"", PatchId, "\",\"CveId\":\"",CVEId,"\",\"Type\":\"",CVEType,"\",\"desc\":\"", description, "\"}"}
			end
			bfind = true
		end 

        if math.mod(for_count,gc_count) == 0 then
            collectgarbage("collect")
        end
        for_count = for_count + 1
	end

	result = table.concat{result, "]}"}

    collectgarbage("collect")
    collectgarbage("restart")

    return result
end

--ScanFun()